insert into public.exercises (key, owner, public, data) values ('kb_swing', null, true, '{"name":"Kettlebell swings","video":"bDCeXbMJVNs","unit":"kg","step":4,"icon":"kettlebell","color":"#f59e0b","cue":"Hinge, not squat. Snap the hips, arms are ropes, bell to chest height."}'::jsonb) on conflict (key) do update set data = excluded.data;
