insert into public.workouts (id, owner, creator, title, public, data) values ('priyanka-swings-incline-press-sprints', null, 'Priyanka', 'Swings, incline press & sprints', true, '{"id":"priyanka-swings-incline-press-sprints","title":"Swings, incline press & sprints","creator":"Priyanka","created":"2026-09-02","level":"Hard","tags":["HIIT","Kettlebell","Treadmill"],"blocks":[{"name":"Swings + incline press","type":"interval","work_s":30,"rest_s":30,"rounds":8,"exercises":[{"ex":"kb_swing","target":28},{"ex":"db_incline_press","target":15}]},{"name":"Sprints","type":"interval","work_s":30,"rest_s":30,"rounds":8,"exercises":[{"ex":"sprint","target":14.5}]},{"name":"Swings + lateral raises","type":"interval","work_s":30,"rest_s":30,"rounds":4,"exercises":[{"ex":"kb_swing","target":28},{"ex":"lat_raise","target":7.5}]},{"name":"Incline walk","type":"steady","ex":"incline_walk","incline":6,"repeat":2,"segments":[{"s":120,"speed":6},{"s":180,"speed":9}]}]}'::jsonb) on conflict (id) do update set data = excluded.data, title = excluded.title, creator = excluded.creator;
insert into public.workouts (id, owner, creator, title, public, data) values ('priyanka-swings-press-sprints', null, 'Priyanka', 'Swings, shoulder press & sprints', true, '{"id":"priyanka-swings-press-sprints","title":"Swings, shoulder press & sprints","creator":"Priyanka","created":"2026-08-23","level":"Hard","tags":["HIIT","Kettlebell","Treadmill"],"blocks":[{"name":"Swings + shoulder press","type":"interval","work_s":30,"rest_s":30,"rounds":8,"exercises":[{"ex":"kb_swing","target":28},{"ex":"db_shoulder_press","target":15}]},{"name":"Sprints","type":"interval","work_s":30,"rest_s":30,"rounds":8,"exercises":[{"ex":"sprint","target":14.5}]},{"name":"Swings","type":"interval","work_s":30,"rest_s":30,"rounds":8,"exercises":[{"ex":"kb_swing","target":24}]},{"name":"Lateral raises","type":"interval","work_s":30,"rest_s":30,"rounds":2,"exercises":[{"ex":"lat_raise","target":7.5}]},{"name":"Incline walk","type":"steady","ex":"incline_walk","incline":6,"repeat":3,"segments":[{"s":120,"speed":6},{"s":180,"speed":9}]}]}'::jsonb) on conflict (id) do update set data = excluded.data, title = excluded.title, creator = excluded.creator;
